import {SITE} from './config.js';
import {products,productById,CATEGORY_LABELS} from './products.js';
import {sanitizeCart,changeQuantity,countItems,cartTotal,money,formatPhone,isValidPhone,buildMessage,canCheckout} from './cart.js';
const id=x=>document.getElementById(x);
const ids=products.map(p=>p.id);
const STORAGE_KEY='hs-processados-carrinho-v2';
const icons={plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m4 12 5 5L20 6"/></svg>'};
let cart={};try{cart=sanitizeCart(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'),ids)}catch{cart={}}
let category='all',query='',sort='featured',lastFocus=null,toastTimer=null;
const approved=canCheckout(SITE);
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
function node(tag,attrs={},children=[]){const n=document.createElement(tag);for(const [k,v] of Object.entries(attrs)){if(k==='class')n.className=v;else if(k==='text')n.textContent=v;else if(k==='html')n.innerHTML=v;else n.setAttribute(k,v)}children.forEach(c=>n.append(c));return n}
function notify(msg){const el=id('toast');el.textContent=msg;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,2600)}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(cart))}catch{/* storage may be unavailable */}}
function setCart(newCart){cart=newCart;save();renderCart()}
function productCard(p,index){
 const card=node('article',{class:'product-card'});card.style.setProperty('--i',index);
 const pic=node('div',{class:'product-photo'});const img=node('img',{src:p.image,alt:p.alt,loading:index<2?'eager':'lazy',decoding:'async',width:'600',height:'600'});pic.append(img);if(p.badge)pic.append(node('span',{class:'product-tag',text:p.badge}));
 const body=node('div',{class:'product-body'});body.append(node('span',{class:'product-category',text:CATEGORY_LABELS[p.category]}),node('h3',{text:p.name}),node('p',{class:'product-description',text:p.description}));
 const priceWrap=node('div');priceWrap.append(node('span',{class:'price-label',text:'Valor demonstrativo'}),node('strong',{class:'price',text:money(p.price)}));
 const add=node('button',{type:'button',class:'add-button','aria-label':`Adicionar ${p.name} ao pedido`,title:`Adicionar ${p.name}`,html:icons.plus});add.addEventListener('click',()=>{setCart(changeQuantity(cart,p.id,1,ids));add.innerHTML=icons.check;add.classList.add('added');add.setAttribute('aria-label',`${p.name} adicionado`);notify(`${p.name} adicionado ao pedido`);setTimeout(()=>{if(add.isConnected){add.innerHTML=icons.plus;add.classList.remove('added');add.setAttribute('aria-label',`Adicionar ${p.name} ao pedido`)}},900)});
 const row=node('div',{class:'product-price-row'},[priceWrap,add]);body.append(row);card.append(pic,body);return card
}
function renderFilters(){const host=id('filters');host.replaceChildren();for(const [key,label] of Object.entries(CATEGORY_LABELS)){const b=node('button',{type:'button',class:`filter-pill${category===key?' active':''}`,text:label,'aria-pressed':String(category===key)});b.addEventListener('click',()=>{category=key;renderFilters();renderProducts()});host.append(b)}}
function renderProducts(){let list=products.filter(p=>(category==='all'||p.category===category)&&normalize(`${p.name} ${p.description}`).includes(query));if(sort==='lowest')list.sort((a,b)=>a.price-b.price);if(sort==='highest')list.sort((a,b)=>b.price-a.price);if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const host=id('products');host.replaceChildren(...list.map(productCard));host.setAttribute('aria-busy','false');id('empty-state').hidden=Boolean(list.length)}
function renderCart(){
 const count=countItems(cart),sum=cartTotal(cart,products);id('cart-count').textContent=String(count);id('cart-heading-count').textContent=`(${count})`;id('menu-cart-count').textContent=`(${count})`;id('cart-subtotal').textContent=money(sum);id('sticky-count').textContent=`${count} ${count===1?'item':'itens'}`;id('sticky-total').textContent=money(sum);id('sticky-cart').hidden=count===0;document.querySelector('.cart-trigger').setAttribute('aria-label',`Abrir pedido com ${count} ${count===1?'item':'itens'}`);
 const host=id('cart-items');host.replaceChildren();if(!count){host.append(node('div',{class:'cart-empty'},[node('span',{text:'✳','aria-hidden':'true'}),node('h3',{text:'Sua seleção começa aqui.'}),node('p',{text:'Escolha os produtos e monte seu pedido em poucos passos.'})]));return}
 for(const p of products){const qty=cart[p.id];if(!qty)continue;const item=node('div',{class:'cart-item'});item.append(node('img',{src:p.image,alt:'',width:'67',height:'67',loading:'lazy'}));const info=node('div',{class:'cart-item-info'},[node('strong',{text:p.name}),node('small',{text:'Valor demonstrativo'}),node('b',{text:money(p.price*qty)})]);const qtyControls=node('div',{class:'qty-controls'});const minus=node('button',{type:'button',text:'−','aria-label':`Diminuir ${p.name}`}),plus=node('button',{type:'button',text:'+','aria-label':`Aumentar ${p.name}`});minus.addEventListener('click',()=>setCart(changeQuantity(cart,p.id,-1,ids)));plus.addEventListener('click',()=>setCart(changeQuantity(cart,p.id,1,ids)));qtyControls.append(minus,node('span',{text:String(qty)}),plus);item.append(info,qtyControls);host.append(item)}
}
function openCart(){lastFocus=document.activeElement;id('cart-overlay').hidden=false;id('cart-panel').classList.add('open');id('cart-panel').setAttribute('aria-hidden','false');document.querySelector('.cart-trigger').setAttribute('aria-expanded','true');document.body.classList.add('modal-open');id('cart-close').focus();id('form-error').hidden=true}
function closeCart(){id('cart-panel').classList.remove('open');id('cart-panel').setAttribute('aria-hidden','true');id('cart-overlay').hidden=true;document.querySelector('.cart-trigger').setAttribute('aria-expanded','false');document.body.classList.remove('modal-open');lastFocus?.focus()}
function showError(message,field){const el=id('form-error');el.textContent=message;el.hidden=false;field?.focus();el.scrollIntoView({block:'nearest',behavior:'smooth'})}
function getMessage(){return buildMessage({cart,products,name:id('customer-name').value,phone:id('customer-phone').value,fulfillment:id('fulfillment').value,address:id('customer-address').value,payment:id('payment').value,notes:id('notes').value,isDemo:!approved})}
function validate(){if(!countItems(cart))return showError('Escolha ao menos um produto.');const name=id('customer-name');if(!name.value.trim())return showError('Informe seu nome.',name);const phone=id('customer-phone');if(!isValidPhone(phone.value))return showError('Informe um WhatsApp válido com DDD.',phone);if(!id('privacy-agree').checked)return showError('Confirme que leu a informação de privacidade.',id('privacy-agree'));return true}
function openPreview(){if(validate()!==true)return;id('form-error').hidden=true;id('preview-message').textContent=getMessage();const send=id('send-request');send.disabled=!approved;id('preview-note').textContent=approved?'Ao continuar, o WhatsApp abrirá com a mensagem para o número comercial do HS.':'PRÉVIA: envio desativado até confirmação do número oficial do HS e aprovação de todos os dados.';closeCart();id('preview-dialog').showModal()}
function trapDrawer(e){if(!id('cart-panel').classList.contains('open')||e.key!=='Tab')return;const f=[...id('cart-panel').querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href]')].filter(x=>x.getClientRects().length);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
for(const b of document.querySelectorAll('[data-open-cart]'))b.addEventListener('click',()=>{id('mobile-nav').hidden=true;id('menu-toggle').setAttribute('aria-expanded','false');openCart()});
id('cart-close').addEventListener('click',closeCart);id('cart-overlay').addEventListener('click',closeCart);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&id('cart-panel').classList.contains('open'))closeCart();else trapDrawer(e)});
id('menu-toggle').addEventListener('click',()=>{const menu=id('mobile-nav');menu.hidden=!menu.hidden;id('menu-toggle').setAttribute('aria-expanded',String(!menu.hidden))});for(const a of id('mobile-nav').querySelectorAll('a'))a.addEventListener('click',()=>{id('mobile-nav').hidden=true;id('menu-toggle').setAttribute('aria-expanded','false')});
id('search').addEventListener('input',e=>{query=normalize(e.target.value);renderProducts()});id('sort').addEventListener('change',e=>{sort=e.target.value;renderProducts()});id('clear-filters').addEventListener('click',()=>{category='all';query='';sort='featured';id('search').value='';id('sort').value='featured';renderFilters();renderProducts()});
id('customer-phone').addEventListener('input',e=>{const start=e.target.selectionStart;e.target.value=formatPhone(e.target.value)});
id('checkout-form').addEventListener('submit',e=>{e.preventDefault();openPreview()});id('preview-close').addEventListener('click',()=>id('preview-dialog').close());id('copy-request').addEventListener('click',async()=>{const val=id('preview-message').textContent;try{await navigator.clipboard.writeText(val);notify('Resumo copiado!')}catch{const ta=document.createElement('textarea');ta.value=val;document.body.append(ta);ta.select();const result=document.execCommand('copy');ta.remove();notify(result?'Resumo copiado!':'Selecione e copie o texto do resumo.')}});
id('send-request').addEventListener('click',()=>{if(!approved)return;const url=`https://wa.me/${SITE.whatsapp}?text=${encodeURIComponent(getMessage())}`;window.open(url,'_blank','noopener,noreferrer')});
renderFilters();renderProducts();renderCart();
